VALUES ('primka-parametricka-obecna-v1','primka-parametricka-obecna',1,'Přímka: parametrická a obecná rovnice — self-check (24 úloh)','24 úloh / 48 bodů / 35 minut. Parametrické vyjádření, obecná rovnice, směrový a normálový vektor, převody, průsečíky a vzájemná poloha přímek. Po přiřazení serverové vyhodnocení s vysvětlením a uložením výsledků.','Matematika','Analytická geometrie – přímka','SŠ / maturita',35,'published');

INSERT OR IGNORE INTO self_check_questions
(id,test_id,position,prompt,options_json,correct_answer,explanation,points)
VALUES
('primka-parametricka-obecna-v1-q01','primka-parametricka-obecna-v1',1,'{"instruction":"Přímka: x = 2 + 3t, y = −1 + 2t. Jaká je souřadnice x pro t = 2?","category":"Parametrické vyjádření","hint":"Dosaď t = 2 do první rovnice."}','[{"id":"a","label":"[[math:9]]"},{"id":"b","label":"[[math:7]]"},{"id":"c","label":"[[math:-8]]"},{"id":"d","label":"[[math:8]]"}]','d','x = 2 + 3·2 = 8.',2),
('primka-parametricka-obecna-v1-q02','primka-parametricka-obecna-v1',2,'{"instruction":"Stejná přímka: x = 2 + 3t, y = −1 + 2t. Jaká je souřadnice y pro t = 2?","category":"Parametrické vyjádření","hint":"Dosaď t = 2 do druhé rovnice."}','[{"id":"a","label":"[[math:2]]"},{"id":"b","label":"[[math:-3]]"},{"id":"c","label":"[[math:3]]"},{"id":"d","label":"[[math:4]]"}]','c','y = −1 + 2·2 = 3.',2),
('primka-parametricka-obecna-v1-q03','primka-parametricka-obecna-v1',3,'{"instruction":"Prochází přímka x = −1 + 2t, y = 4 − 3t bodem B = (3,−2)? Odpověz ano/ne.","category":"Parametrické vyjádření","hint":"Z x vypočítej t a ověř stejné t v y."}','[{"id":"a","label":"Ne"},{"id":"b","label":"Ano"}]','b','3 = −1 + 2t → t = 2; y = 4 − 3·2 = −2. Ano.',2),
('primka-parametricka-obecna-v1-q04','primka-parametricka-obecna-v1',4,'{"instruction":"Prochází přímka x = 1 + 2t, y = 3 − t bodem B = (5,2)? Odpověz ano/ne.","category":"Parametrické vyjádření","hint":"Pro x = 5 musí být t = 2; podívej se na y."}','[{"id":"a","label":"Ano"},{"id":"b","label":"Ne"}]','b','Pro x = 5 je t = 2, pak y = 1, ne 2. Ne.',2),
('primka-parametricka-obecna-v1-q05','primka-parametricka-obecna-v1',5,'{"instruction":"A = (1,2), B = (4,8). Kolik je první složka vektoru AB = B − A?","category":"Parametrické vyjádření","hint":"Odečti x-ové souřadnice Bₓ − Aₓ."}','[{"id":"a","label":"[[math:4]]"},{"id":"b","label":"[[math:2]]"},{"id":"c","label":"[[math:-3]]"},{"id":"d","label":"[[math:3]]"}]','d','AB = (4 − 1, 8 − 2) = (3,6). První složka je 3.',2),
('primka-parametricka-obecna-v1-q06','primka-parametricka-obecna-v1',6,'{"instruction":"A = (1,2), B = (4,8). Kolik je druhá složka vektoru AB = B − A?","category":"Parametrické vyjádření","hint":"Odečti y-ové souřadnice Bᵧ − Aᵧ."}','[{"id":"a","label":"[[math:5]]"},{"id":"b","label":"[[math:-6]]"},{"id":"c","label":"[[math:6]]"},{"id":"d","label":"[[math:7]]"}]','c','AB = (3,6), tedy druhá složka je 6.',2),
('primka-parametricka-obecna-v1-q07','primka-parametricka-obecna-v1',7,'{"instruction":"Přímka 2x − 3y + c = 0 prochází bodem A = (1,2). Urči c.","category":"Obecná rovnice","hint":"Dosaď x = 1 a y = 2 a vyjádři c."}','[{"id":"a","label":"[[math:-4]]"},{"id":"b","label":"[[math:4]]"},{"id":"c","label":"[[math:5]]"},{"id":"d","label":"[[math:3]]"}]','b','2·1 − 3·2 + c = 0 → −4 + c = 0 → c = 4.',2),
('primka-parametricka-obecna-v1-q08','primka-parametricka-obecna-v1',8,'{"instruction":"Přímka 4x − 5y + 10 = 0. Jaká je první složka normálového vektoru n = (a,b)?","category":"Obecná rovnice","hint":"Koeficienty u x a y tvoří normálový vektor."}','[{"id":"a","label":"[[math:4]]"},{"id":"b","label":"[[math:5]]"},{"id":"c","label":"[[math:3]]"},{"id":"d","label":"[[math:-4]]"}]','a','n = (4,−5), první složka je 4.',2),
('primka-parametricka-obecna-v1-q09','primka-parametricka-obecna-v1',9,'{"instruction":"Přímka 3x + 2y − 6 = 0. Zvol u = (b,−a). Jaká je druhá složka u?","category":"Obecná rovnice","hint":"a = 3, b = 2; směrový vektor (b,−a)."}','[{"id":"a","label":"[[math:-2]]"},{"id":"b","label":"[[math:-4]]"},{"id":"c","label":"[[math:3]]"},{"id":"d","label":"[[math:-3]]"}]','d','u = (2,−3); druhá složka je −3.',2),
('primka-parametricka-obecna-v1-q10','primka-parametricka-obecna-v1',10,'{"instruction":"Přímka x − 2y + 4 = 0. Kde protíná osu x? Zadej souřadnici x.","category":"Obecná rovnice","hint":"Na ose x platí y = 0."}','[{"id":"a","label":"[[math:-5]]"},{"id":"b","label":"[[math:4]]"},{"id":"c","label":"[[math:-4]]"},{"id":"d","label":"[[math:-3]]"}]','c','x − 2·0 + 4 = 0 → x = −4.',2),
('primka-parametricka-obecna-v1-q11','primka-parametricka-obecna-v1',11,'{"instruction":"Přímka 2x + 3y − 12 = 0. Kde protíná osu y? Zadej souřadnici y.","category":"Obecná rovnice","hint":"Na ose y platí x = 0."}','[{"id":"a","label":"[[math:-4]]"},{"id":"b","label":"[[math:4]]"},{"id":"c","label":"[[math:5]]"},{"id":"d","label":"[[math:3]]"}]','b','3y − 12 = 0 → y = 4.',2),
('primka-parametricka-obecna-v1-q12','primka-parametricka-obecna-v1',12,'{"instruction":"Leží bod B = (−1,2) na přímce 5x − y + 7 = 0? Odpověz ano/ne.","category":"Obecná rovnice","hint":"Spočítej 5·(−1) − 2 + 7."}','[{"id":"a","label":"Ano"},{"id":"b","label":"Ne"}]','a','−5 − 2 + 7 = 0. Ano.',2),
('primka-parametricka-obecna-v1-q13','primka-parametricka-obecna-v1',13,'{"instruction":"A = (1,2), u = (3,4). Zvol normálu n = (−v,u). Jaké vyjde c v ax + by + c = 0?","category":"Převody rovnic","hint":"n = (−4,3), a pak dosaď A."}','[{"id":"a","label":"[[math:-1]]"},{"id":"b","label":"[[math:-3]]"},{"id":"c","label":"[[math:2]]"},{"id":"d","label":"[[math:-2]]"}]','d','−4·1 + 3·2 + c = 0 → c = −2.',2),
('primka-parametricka-obecna-v1-q14','primka-parametricka-obecna-v1',14,'{"instruction":"A = (1,2), u = (3,4). Zvol n = (−v,u). Jaký je koeficient a u x?","category":"Převody rovnic","hint":"Normála je (−v,u) = (−4,3)."}','[{"id":"a","label":"[[math:-5]]"},{"id":"b","label":"[[math:4]]"},{"id":"c","label":"[[math:-4]]"},{"id":"d","label":"[[math:-3]]"}]','c','Koeficient a = −v = −4.',2),
('primka-parametricka-obecna-v1-q15','primka-parametricka-obecna-v1',15,'{"instruction":"A = (−2,1), u = (1,−2). Zvol n = (−v,u). Jaké je c?","category":"Převody rovnic","hint":"n = (2,1). Dosadíš −2 a 1."}','[{"id":"a","label":"[[math:-3]]"},{"id":"b","label":"[[math:3]]"},{"id":"c","label":"[[math:4]]"},{"id":"d","label":"[[math:2]]"}]','b','2·(−2) + 1 + c = 0 → c = 3.',2),
('primka-parametricka-obecna-v1-q16','primka-parametricka-obecna-v1',16,'{"instruction":"A = (0,5), u = (2,0). Zvol n = (−v,u) a rovnici před zkrácením. Kolik je c?","category":"Převody rovnic","hint":"n = (0,2) → 0x + 2y + c = 0."}','[{"id":"a","label":"[[math:-10]]"},{"id":"b","label":"[[math:-9]]"},{"id":"c","label":"[[math:-11]]"},{"id":"d","label":"[[math:10]]"}]','a','2·5 + c = 0 → c = −10. Rovnici lze následně zkrátit na y − 5 = 0.',2),
('primka-parametricka-obecna-v1-q17','primka-parametricka-obecna-v1',17,'{"instruction":"Obecná rovnice 3x − 4y + 12 = 0. Pro x₀ = 0 určete y₀ bodu přímky.","category":"Převody rovnic","hint":"Dosaď x = 0."}','[{"id":"a","label":"[[math:4]]"},{"id":"b","label":"[[math:2]]"},{"id":"c","label":"[[math:-3]]"},{"id":"d","label":"[[math:3]]"}]','d','−4y + 12 = 0 → y = 3; bod A = (0,3).',2),
('primka-parametricka-obecna-v1-q18','primka-parametricka-obecna-v1',18,'{"instruction":"Obecná rovnice −2x + y − 5 = 0. Pro y₀ = 0 určete x₀ bodu přímky.","category":"Převody rovnic","hint":"Dosaď y = 0; hodnota je −5/2."}','[{"id":"a","label":"[[math:-3]]"},{"id":"b","label":"[[math:2{,}5]]"},{"id":"c","label":"[[math:-2{,}5]]"},{"id":"d","label":"[[math:-2]]"}]','c','−2x − 5 = 0 → x = −5/2 = −2,5.',2),
('primka-parametricka-obecna-v1-q19','primka-parametricka-obecna-v1',19,'{"instruction":"Jsou přímky x + y − 4 = 0 a 2x + 2y + 1 = 0 rovnoběžné? Odpověz ano/ne.","category":"Vzájemná poloha a průsečíky","hint":"Porovnej normály (1,1) a (2,2)."}','[{"id":"a","label":"Ne"},{"id":"b","label":"Ano"}]','b','Normály jsou násobky. Přímky jsou rovnoběžné (a nejsou totožné).',2),
('primka-parametricka-obecna-v1-q20','primka-parametricka-obecna-v1',20,'{"instruction":"Jsou přímky x + y − 4 = 0 a x − y = 0 kolmé? Odpověz ano/ne.","category":"Vzájemná poloha a průsečíky","hint":"Zkus skalární součin jejich normál."}','[{"id":"a","label":"Ano"},{"id":"b","label":"Ne"}]','a','(1,1)·(1,−1) = 1 − 1 = 0. Ano.',2),
('primka-parametricka-obecna-v1-q21','primka-parametricka-obecna-v1',21,'{"instruction":"Průsečík přímek x + y = 5 a x − y = 1: kolik je x?","category":"Vzájemná poloha a průsečíky","hint":"Sečti obě rovnice."}','[{"id":"a","label":"[[math:4]]"},{"id":"b","label":"[[math:2]]"},{"id":"c","label":"[[math:-3]]"},{"id":"d","label":"[[math:3]]"}]','d','2x = 6 → x = 3.',2),
('primka-parametricka-obecna-v1-q22','primka-parametricka-obecna-v1',22,'{"instruction":"Průsečík přímek x + y = 5 a x − y = 1: kolik je y?","category":"Vzájemná poloha a průsečíky","hint":"Dosadíš vypočtené x = 3."}','[{"id":"a","label":"[[math:1]]"},{"id":"b","label":"[[math:-2]]"},{"id":"c","label":"[[math:2]]"},{"id":"d","label":"[[math:3]]"}]','c','3 + y = 5 → y = 2.',2),
('primka-parametricka-obecna-v1-q23','primka-parametricka-obecna-v1',23,'{"instruction":"Vzdálenost počátku O = (0,0) od přímky 3x + 4y − 10 = 0. Kolik jednotek?","category":"Vzájemná poloha a průsečíky","hint":"Použij |ax₀ + by₀ + c| / √(a²+b²)."}','[{"id":"a","label":"[[math:-2]]"},{"id":"b","label":"[[math:2]]"},{"id":"c","label":"[[math:3]]"},{"id":"d","label":"[[math:1]]"}]','b','|−10| / √(9 + 16) = 10/5 = 2.',2),
('primka-parametricka-obecna-v1-q24','primka-parametricka-obecna-v1',24,'{"instruction":"Směrový vektor přímky je u = (2,3). Jaká je směrnice k = v/u?","category":"Vzájemná poloha a průsečíky","hint":"k = 3/2; zadej 1,5 nebo 3/2."}','[{"id":"a","label":"[[math:1{,}5]]"},{"id":"b","label":"[[math:2]]"},{"id":"c","label":"[[math:1]]"},{"id":"d","label":"[[math:-1{,}5]]"}]','a','k = 3/2 = 1,5. Přímka není svislá, protože u ≠ 0.',2);
